/* GDPR fine benchmark data, bundled with the web part.

   Fines, dates, sectors, Articles and the violation classification come from the
   GDPR enforcement tracker, by way of the Power BI export of 20 September 2026,
   with the cases that export drops (year-only decision dates) carried over.
   Article names are the model's own lookup table.
   Turnover is not in that source: it was researched separately from annual
   reports, statutory filings and national company registers, and each row
   carries a confidence and a source for it.

   357 decisions carry both a fine and a turnover.

   Generated by tools/build-fine-data.js. Do not hand edit. Regenerate from the
   website's calculator-data.js so the web part and the website always answer the
   same question the same way. */

export type FineRow = [
  string,  /* etid     */
  string,  /* company  */
  string,  /* country  */
  number,  /* year     */
  number,  /* fine     */
  number,  /* turnover */
  string,  /* type     */
  string,  /* sector   */
  string[],/* articles */
  string,  /* tier     */  /* "2%" or "4%", as the source records it */
  number,  /* conf     */
  number,  /* fin      */
  string,  /* tyear    */
  string,  /* tbasis   */
  string,  /* tsource  */
  number   /* ep       */
];

export interface FineType {
  code: string;
  label: string;
  note: string;
  thin?: boolean;
}

export const FINE_FIELDS: string[] = ["etid","company","country","year","fine","turnover","type","sector","articles","tier","conf","fin","tyear","tbasis","tsource","ep"];

