export const FINE_TYPES: FineType[] = [
  {
    code: "security",
    label: "Security failure, unauthorised access or breach",
    note: "Typically Art. 32, often with Art. 5(1)(f). Hacking and ransomware, but also lost or stolen devices, paper files left where anyone could read them, wrong folder permissions, data sent to the wrong recipient, and systems running without encryption or access control. This is what most organisations mean when they say they had an incident."
  },
  {
    code: "legal-basis",
    label: "No valid legal basis for the processing",
    note: "Typically Art. 6, usually alongside Art. 5. Marketing calls, emails and texts without valid consent; legitimate interest stretched further than it goes; consent that was bundled, pre-ticked or impossible to refuse; CCTV and employee monitoring with no basis; and data shared with third parties nobody agreed to. The single largest category in the enforcement record."
  },
  {
    code: "principles",
    label: "General processing principles",
    note: "Typically Art. 5. Collecting more than the purpose needs, keeping it long after that purpose ended, using it for something it was never collected for, records that are wrong and were never corrected, and processing the organisation cannot account for. More often cited alongside another failure than on its own."
  },
  {
    code: "rights",
    label: "Data subject rights not honoured",
    note: "Typically Art. 12 to 22. Access requests ignored, answered late or answered in part; erasure refused with no lawful ground; objections to marketing not acted on; and rights made deliberately hard to exercise by hiding them behind a form, a phone line or a login. Usually set off by one complainant rather than by a regulator's own audit."
  },
  {
    code: "cooperation",
    label: "Failure to cooperate with the authority",
    note: "Art. 31 and 58. Not replying to the authority, missing its deadlines, answering incompletely, or obstructing an inspection. Almost always an addition to another finding, and the one category where the fine reflects behaviour during the investigation rather than the original failure. Thin evidence base, so read the peer count."
  },
  {
    code: "information",
    label: "Information obligations",
    thin: true,
    note: "Art. 12 to 14. No privacy notice at all, or one that is unreadable, incomplete, or silent on who the data is shared with and how long it is kept. Common in practice but rarely fined on its own against an organisation whose turnover is published, so there are too few peers here to benchmark."
  },
  {
    code: "breach",
    label: "Breach notification obligations",
    thin: true,
    note: "Art. 33 and 34. Not telling the authority within 72 hours, not telling the people affected when the risk to them was high, or notifying with so little detail that it did not count. Enforced almost entirely against public bodies and small organisations with no published turnover, so it cannot be benchmarked."
  },
  {
    code: "dpo",
    label: "DPO involvement",
    thin: true,
    note: "Art. 37 to 39. No DPO appointed where one was required, the role handed to someone with a conflict of interest, or a DPO who exists on paper but is never involved in decisions and cannot be reached by data subjects. Only five comparable cases carry a turnover, so no benchmark is possible."
  },
  {
    code: "dpa",
    label: "Processing agreement",
    thin: true,
    note: "Art. 28. No written contract with a processor, a contract missing the terms Art. 28(3) requires, or a sub-processor brought in without permission. Two comparable cases carry a turnover, so this category is here for completeness rather than for use."
  }
];

